// Package proto preserves the former import path for generated name messages.
package proto

import canonical "github.com/montevive/go-name-detector/pkg/proto"

// NameEntry is the canonical generated NameEntry type.
type NameEntry = canonical.NameEntry

// NameDataset is the canonical generated NameDataset type.
type NameDataset = canonical.NameDataset

// CombinedNameDataset is the canonical generated CombinedNameDataset type.
type CombinedNameDataset = canonical.CombinedNameDataset

// File_proto_names_proto is the canonical names file descriptor.
var File_proto_names_proto = canonical.File_proto_names_proto
